SELECT 
FROM worker_info
WHERE 1=1

    AND name LIKE CONCAT('%', #{name}, '%')


    AND phone = #{phone}


    AND level = #{level}


    AND status = #{status}

ORDER BY create_time DESC

SELECT 
FROM worker_info
WHERE 1=1

    AND name LIKE CONCAT('%', #{worker.name}, '%')


    AND phone = #{worker.phone}


    AND level = #{worker.level}


    AND status = #{worker.status}

ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

